def img(name,alt,cls='',eager=False):
 return f'<img class="{cls}" src="assets/{name}.webp" alt="{e(alt)}" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'

