 body=intro+menu+f'<div id="descubrir"></div><section class="quote-section" id="filosofia"><div class="wrap">{kicker("Nuestra forma de hacerlo")}<p>«{d["quote"]}»</p></div></section>'+sections+opts+(comparator() if slug=='rubios' else '')+work+f'<div id="preguntas">{faqs(d["faq"])}</div>'
